package pfm.android;

import android.app.*;import android.content.*;import android.graphics.Typeface;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;

/** Read-only cross-league market/economy preview; transactions remain disabled until persistence is ready. */
public final class NativeGlobalMarket{
 private NativeGlobalMarket(){} static class R{String code,club;NativeWorldCenter.P p;}
 static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);} static TextView tx(Context c,String s,float z,boolean b){TextView v=new TextView(c);v.setText(s);v.setTextSize(z);v.setPadding(dp(c,8),dp(c,5),dp(c,8),dp(c,5));if(b)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 static String pos(int p){return p==0?"GK":p==1?"DEF":p==2?"MID":"FW";} static String money(int n){if(n>=1000000)return String.format(Locale.US,"£%.1fm",n/1000000.0);if(n>=1000)return "£"+(n/1000)+"k";return "£"+n;}
 static int budget(){try{return ((Number)Class.forName("PfmTransferBridge").getMethod("budget").invoke(null)).intValue();}catch(Throwable t){return 0;}}
 static String league(String c){for(int i=0;i<NativeWorldCenter.C.length;i++)if(c.equals(NativeWorldCenter.C[i]))return NativeWorldCenter.N[i];return c;}
 static void profile(Activity a,R r,int cash){NativeWorldCenter.P p=r.p;String body="Club: "+r.club+" ("+league(r.code)+")\nNationality: "+p.nat.split(" • ")[0]+"\nPosition: "+pos(p.pos)+"   Age: "+p.age+"\nSPE "+p.spe+"   RES "+p.res+"   QUA "+p.qua+"   OVR "+p.ovr+"\n\nDatabase value: "+money(p.value)+"\nAnnual wage basis: "+money(p.wage)+"\nYour current budget: "+money(cash)+"\nAffordability: "+(cash>=p.value?"within transfer budget":"over transfer budget")+"\n\nPreview only: cross-league bids are intentionally disabled until transfer persistence and AI squad replacement are implemented.";new AlertDialog.Builder(a).setTitle(p.name).setMessage(body).setPositiveButton("Close",null).show();}
 public static void show(Activity a,ArrayList<String> codes){int cash=budget();ArrayList<R> all=new ArrayList<R>();for(String c:codes)for(NativeWorldCenter.T t:NativeWorldCenter.leagues.get(c))for(NativeWorldCenter.P p:t.ps){R r=new R();r.code=c;r.club=t.name;r.p=p;all.add(r);}LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(a,8),0,dp(a,8),0);TextView summary=tx(a,"Global pool: "+all.size()+" players   •   Budget "+money(cash)+"\nRead-only economy preview; tap a player for valuation details.",12f,false);root.addView(summary);EditText search=new EditText(a);search.setHint("Player, club or nationality");search.setSingleLine(true);root.addView(search);LinearLayout controls=new LinearLayout(a);Spinner position=new Spinner(a),sort=new Spinner(a);position.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"ALL POSITIONS","GK","DEF","MID","FW"}));sort.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"VALUE","OVERALL","AGE","NAME"}));controls.addView(position,new LinearLayout.LayoutParams(0,-2,1));controls.addView(sort,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);ArrayList<R> shown=new ArrayList<R>();ArrayAdapter<R> adapter=new ArrayAdapter<R>(a,android.R.layout.simple_list_item_1,shown){public View getView(int n,View old,ViewGroup parent){R r=getItem(n);LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.VERTICAL);row.addView(tx(a,r.p.name+"  ·  "+r.club+"  ·  "+league(r.code),14f,true));row.addView(tx(a,pos(r.p.pos)+"  OVR "+r.p.ovr+"  AGE "+r.p.age+"   VALUE "+money(r.p.value)+(cash>=r.p.value?"  ✓ affordable":""),11.5f,false));return row;}};ListView list=new ListView(a);list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));Runnable refresh=()->{String q=search.getText().toString().toLowerCase(Locale.US),pf=String.valueOf(position.getSelectedItem());shown.clear();for(R r:all){String country=r.p.nat.split(" • ")[0];if(!"ALL POSITIONS".equals(pf)&&!pf.equals(pos(r.p.pos)))continue;if(q.length()>0&&!(r.p.name+" "+r.club+" "+country+" "+league(r.code)).toLowerCase(Locale.US).contains(q))continue;shown.add(r);}String s=String.valueOf(sort.getSelectedItem());Collections.sort(shown,(x,y)->"OVERALL".equals(s)?y.p.ovr-x.p.ovr:"AGE".equals(s)?x.p.age-y.p.age:"NAME".equals(s)?x.p.name.compareToIgnoreCase(y.p.name):y.p.value-x.p.value);summary.setText("Shown: "+shown.size()+" / "+all.size()+"   •   Budget "+money(cash)+"\nRead-only economy preview; tap a player for valuation details.");adapter.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});android.widget.AdapterView.OnItemSelectedListener l=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}};position.setOnItemSelectedListener(l);sort.setOnItemSelectedListener(l);list.setOnItemClickListener((p,v,n,id)->profile(a,shown.get(n),cash));refresh.run();AlertDialog d=new AlertDialog.Builder(a).setTitle("Global Player Market").setView(root).setPositiveButton("Close",null).create();d.setOnShowListener(v->{Window w=d.getWindow();if(w!=null)w.setLayout(-1,Math.round(a.getResources().getDisplayMetrics().heightPixels*.94f));});d.show();}
}
